-- Additive adoption: validates before recording ownership; never rewrites account data.
CREATE TABLE IF NOT EXISTS metatrash_schema_components (
 component VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
 version INT UNSIGNED NOT NULL,
 checksum CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL
) ENGINE=InnoDB;
DELIMITER //
CREATE OR REPLACE PROCEDURE adopt_core_v25()
BEGIN
